"""Writes powerbi/DATA_AUDIT.md: every KPI traced to its source file and recalculated independently with pandas (nothing hard-coded)."""
import os
import numpy as np
import pandas as pd

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
P = lambda *a: os.path.join(ROOT, *a)  # noqa: E731
c = pd.read_csv(P("airline_satisfaction_cleaned.csv"))
t = pd.read_csv(P("airline_satisfaction_tiered.csv"))
mc = pd.read_csv(P("models", "model_comparison.csv")).set_index("Model")
R = ["Departure and Arrival Time Convenience", "Ease of Online Booking", "Check-in Service", "Online Boarding", "Gate Location", "On-board Service",
     "Seat Comfort", "Leg Room Service", "Cleanliness", "Food and Drink", "In-flight Service", "In-flight Wifi Service", "In-flight Entertainment", "Baggage Handling"]
n = len(c)
sat = (c.Satisfaction == "Satisfied")
rated = c[R].stack(); rated = rated[rated > 0]
late = c["Arrival Delay"] > 15
tiers = t.satisfaction_tier.value_counts()
per6 = t.avg_service_rating.mean()
f = c[c.Gender == "Female"]
fer = c[(c.Gender == "Female") & (c.Class == "Economy") & (c["Customer Type"] == "Returning")]
L = []
L += ["# Data audit - sources, calculations and discrepancies", "",
      "Generated by `powerbi/build/audit_data_sources.py`; every value below is recalculated from the CSVs, not typed.", "",
      "## 1. Primary dataset", "",
      "| Check | Result |", "|---|---|",
      f"| `airline_satisfaction_cleaned.csv` | {n:,} rows x {c.shape[1]} columns (one row per passenger) |",
      f"| Neutral or Dissatisfied | {(~sat).sum():,} ({(~sat).mean()*100:.2f}%) |",
      f"| Satisfied | {sat.sum():,} ({sat.mean()*100:.2f}%) |",
      f"| `airline_satisfaction_tiered.csv` | {t.shape[0]:,} rows x {t.shape[1]} columns = cleaned file + `avg_service_rating` + `satisfaction_tier`; the 24 shared columns are identical row by row: {c.reset_index(drop=True).equals(t[list(c.columns)].reset_index(drop=True))} |",
      f"| Tier counts | High {tiers['High']:,}, Average {tiers['Average']:,}, Low {tiers['Low']:,} (total {tiers.sum():,}) |", "",
      "**How Power BI loads it:** `FactPassenger` is built from `airline_satisfaction_cleaned.csv`; only the derived Low/Average/High tier is attached from the tiered file by row position (guarded by a row-count check in Power Query). The binary text column `Satisfaction` is the satisfaction target for every satisfaction measure; `Satisfaction Tier` is used only for tier measures and is never a predictor.", "",
      "## 2. Where the odd totals in earlier screenshots came from (they were filters, not data errors)", "",
      "| Number seen | Exact match in the data |", "|---|---|",
      f"| 65,703 / '66K' passengers, High-tier 20,984 ('21K', 31.94%) | Gender = Female: {len(f):,} passengers; High tier {int((f.satisfaction_tier == 'High').sum()) if 'satisfaction_tier' in f else int((t[t.Gender=='Female'].satisfaction_tier=='High').sum()):,} = {(t[t.Gender=='Female'].satisfaction_tier=='High').mean()*100:.2f}% |",
      f"| 22,243 | Gender = Female + Class = Economy + Customer Type = Returning: {len(fer):,} passengers |",
      "| 129K / 129,487 | no filter (all passengers) |", "",
      "With every slicer cleared the total is the full 129,487. The Satisfaction / tier donuts also add to 129,487.", "",
      "## 3. KPI measures: source, calculation and independently recalculated value", "",
      "| Measure | Source table and DAX | Recalculated from CSV |", "|---|---|---|",
      f"| Total Passengers | `FactPassenger`: DISTINCTCOUNT([Passenger ID]) (one index per cleaned row) | {n:,} |",
      f"| Satisfaction Rate | satisfied / total using `FactPassenger[Satisfaction] = \"Satisfied\"` (binary target) | {sat.mean()*100:.2f}% |",
      f"| Neutral/Dissatisfied Rate | same, `\"Neutral or Dissatisfied\"` | {(~sat).mean()*100:.2f}% |",
      f"| High Tier Count / Rate | `FactPassenger[Satisfaction Tier] = \"High\"` (tier column from the tiered file) | {tiers['High']:,} / {tiers['High']/n*100:.2f}% |",
      f"| Average Service Rating | `FactServiceRating`: AVERAGE([Rating]) where Rating > 0 (zero = not applicable) | {rated.mean():.4f} over {len(rated):,} valid ratings |",
      f"| Avg Arrival / Departure Delay | `FactPassenger`: AVERAGE of delay minutes | {c['Arrival Delay'].mean():.2f} / {c['Departure Delay'].mean():.2f} min |",
      f"| Delayed share (>15 min arrival) | rows with Arrival Delay > 15 / total | {late.mean()*100:.2f}% |",
      f"| Satisfaction Rate - delayed / on time | binary Satisfaction in each group | {sat[late].mean()*100:.2f}% / {sat[~late].mean()*100:.2f}% |",
      f"| Good / Poor rating share | ratings >=4 and 1-2 over rated responses only | {(rated>=4).mean()*100:.2f}% / {(rated<=2).mean()*100:.2f}% |",
      f"| Not Rated share (shown separately, never counted as Poor) | zeros / all responses | {(c[R].stack()==0).mean()*100:.2f}% |",
      *[f"| Satisfaction Rate - {k} | binary Satisfaction by `DimTravel[Class]` | {v*100:.2f}% |" for k, v in c.groupby("Class").apply(lambda g: (g.Satisfaction == "Satisfied").mean(), include_groups=False).items()], "",
      "### Discrepancy to be aware of: Average Service Rating 3.28 vs 3.21",
      f"A teammate card shows 3.21. That is `avg_service_rating` (mean {per6:.4f}) from `satisfaction_tiers.py`, which averages only SIX attributes (Wi-Fi, online boarding, seat comfort, food and drink, entertainment, cleanliness) per passenger, zeros included, and is used only to cut the Low/Average/High tiers. The report's Average Service Rating uses all 14 attributes and excludes zeros ({rated.mean():.4f}), as specified. Both are correct for what they measure; they are different quantities.", "",
      "## 4. Model Performance (committed CSVs vs the values you listed)", "",
      "| Model | Accuracy | Macro F1 | ROC-AUC | Matches your table (4 d.p.) |", "|---|---|---|---|---|"]
exp = {"Logistic Regression": (0.9032, 0.9015, 0.9649), "Random Forest": (0.9606, 0.9598, 0.9936), "XGBoost": (0.9643, 0.9636, 0.9953)}
for mname, (a, b, d) in exp.items():
    r = mc.loc[mname]
    ok = (round(r.Accuracy, 4), round(r["Macro F1"], 4), round(r["ROC-AUC"], 4)) == (a, b, d)
    L.append(f"| {mname} | {r.Accuracy:.4f} | {r['Macro F1']:.4f} | {r['ROC-AUC']:.4f} | {'yes' if ok else 'NO'} |")
L += ["", "Power BI reads `models/model_comparison.csv`, `cross_validation_scores.csv`, `subgroup_model_comparison.csv` and the confusion-matrix CSVs unchanged. Cross-validation means/std-devs, confusion matrices and subgroup metrics are cross-checked in `validation_report.md`.", "",
      "## 5. Relationships and filter flow", "",
      "Star schema, one-to-many, single direction: `DimTravel`, `DimPassengerProfile`, `DimSatisfaction` -> `FactPassenger` and `FactServiceRating`; `DimServiceAttribute` -> `FactServiceRating`; `DimModel` -> model-result tables. Slicers therefore filter passenger and rating visuals and never the SHAP / model-level visuals (those tables have no passenger key). No measure counts rows from the SHAP, tier or model tables.", "",
      "## 6. Checkbox slicers", "Gender, Travel Class, Customer Type and Type of Travel are list (checkbox) slicers on Overview and EDA, synced across both pages."]
open(P("powerbi", "DATA_AUDIT.md"), "w", encoding="utf-8").write("\n".join(L) + "\n")
print("\n".join(L[:30]))
